    for locale, page_data in locales.items():
        path = MESSAGES / f"{locale}.json"
        data = load(path)
        data["pages"] = page_data
        data["nav"]["security"] = nav_security[locale]
        data["nav"]["help"] = nav_help[locale]
        save(path, data)

    # verify sample string
    hy = load(MESSAGES / "hy.json")
    sample = hy["pages"]["security"]["dataProtection"]["body"][0]
    assert "\u0448\u0438\u0444\u0440" not in sample
    assert "bcrypt" not in sample
    print("Merged pages i18n. Sample:", sample[:60] + "...")


